// MIT: see LICENSE.upstream. Octane uses native events and refs as props.
import * as React from 'octane';
import { ScrollArea as ScrollAreaPrimitive } from '@octanejs/base-ui/scroll-area';
import { cn } from 'cn';

function ScrollArea({ className, children, ...props }: ScrollAreaPrimitive.Root.Props) {
	return <ScrollAreaPrimitive.Root
		data-slot="scroll-area"
		className={cn('relative', className)}
		{...props}
	>
		<ScrollAreaPrimitive.Viewport
			data-slot="scroll-area-viewport"
			className="size-full rounded-[inherit] transition-[color,box-shadow] outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-1"
		>{children}</ScrollAreaPrimitive.Viewport>
		<ScrollBar />
		<ScrollAreaPrimitive.Corner />
	</ScrollAreaPrimitive.Root>;
}

function ScrollBar({
	className,
	orientation = 'vertical',
	...props
}: ScrollAreaPrimitive.Scrollbar.Props) {
	return <ScrollAreaPrimitive.Scrollbar
		data-slot="scroll-area-scrollbar"
		data-orientation={orientation}
		orientation={orientation}
		className={cn(
			'data-horizontal:h-2.5 data-horizontal:flex-col data-horizontal:border-t data-horizontal:border-t-transparent data-vertical:h-full data-vertical:w-2.5 data-vertical:border-l data-vertical:border-l-transparent flex touch-none p-px transition-colors select-none',
			className,
		)}
		{...props}
	>
		<ScrollAreaPrimitive.Thumb
			data-slot="scroll-area-thumb"
			className="rounded-full relative flex-1 bg-border"
		/>
	</ScrollAreaPrimitive.Scrollbar>;
}

export { ScrollArea, ScrollBar };
